drop table if exists reportes_data_temporal;
create table reportes_data_temporal (kapp_id INT primary key, reporte_id INT, valor1 VARCHAR(150), valor2 VARCHAR(150), valor3 VARCHAR(150), fecha_update timestamp DEFAULT CURRENT_TIMESTAMP );

DROP PROCEDURE IF EXISTS reportes_data_temporal;

DELIMITER $$
CREATE PROCEDURE reportes_data_temporal (
        IN par_kapp_id int,
        IN par_reporte_id int,
        IN fecha_inicio date,
        IN fecha_fin date
    )
    BEGIN
        delete from reportes_data_temporal where kapp_id=par_kapp_id AND reporte_id=par_reporte_id;  

    select par_kapp_id, par_reporte_id
    , ed.valor, ed3.valor
                            from tx.elementos_datos ed
                                left join tx.elementos_datos ed2 on ed2.id_elemento = ed.id_elemento and ed2.id_ctz = (select id from tx.ctz where id_kapp=par_kapp_id and id_ctz_base=14)
                                left join tx.elementos_datos ed3 on ed3.id_elemento = ed.id_elemento and ed3.id_ctz = (select id from tx.ctz where id_kapp=par_kapp_id and id_ctz_base=19)
            where ed.id_ctz = (select id from tx.ctz where id_kapp=par_kapp_id and id_ctz_base=3) and ed2.valor>0
          group by ed.valor, ed3.valor
    union
    select par_kapp_id, par_reporte_id
    ,ed2.valor id_producto, ed4.valor
                                from elementos e
                                    inner join elementos_datos ed on ed.id_elemento=e.id and ed.id_ctz = (select id from ctz where id_kapp = par_kapp_id and id_ctz_base=6)
                                    inner join elementos_datos ed2 on ed2.id_elemento=e.id and ed2.id_ctz = (select id from ctz where id_kapp = par_kapp_id and id_ctz_base=3)
                                    -- inner join elementos_datos ed3 on ed3.id_elemento=e.id and ed3.id_ctz = (select id from ctz where id_kapp = 6 and id_ctz_base=4)
                                    inner join elementos_datos ed4 on ed4.id_elemento=e.id and ed4.id_ctz = (select id from ctz where id_kapp = par_kapp_id and id_ctz_base=19)
    where id_kapp = par_kapp_id and ed.valor between  fecha_inicio and fecha_fin
    group by ed2.valor, ed4.valor
    union
    select par_kapp_id, par_reporte_id
    , id_producto, edx.valor
                            from tx.inv_lotes_log ll
                            left join tx.elementos_datos edx on edx.id_elemento=ll.id_lote 
                  and edx.id_ctz = (SELECT id FROM tx.ctz where id_kapp=par_kapp_id and id_ctz_base=19)
                where fecha between fecha_inicio and fecha_fin and tipo=5
                            group by id_producto, edx.valor;
        COMMIT;
END $$
DELIMITER ;

GRANT EXECUTE ON PROCEDURE tx.reportes_data_temporal TO  'tx_usuario'@'%' ;

